import random

def has_cycle_of_length(adj, n, length):
    # Check if there is a cycle of a specific length
    # This is a bit slow, but for n=23 it should be fine
    def dfs(curr, start, depth, visited):
        if depth == length:
            return start in adj[curr]

        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                if dfs(neighbor, start, depth + 1, visited):
                    return True
                visited.remove(neighbor)
        return False

    for i in range(n):
        if dfs(i, i, 1, {i}):
            return True
    return False

def is_girth_at_least_6(adj, n):
    # Check for cycles of length 3, 4, 5
    for length in [3, 4, 5]:
        if has_cycle_of_length(adj, n, length):
            return False
    return True

def solve():
    n = 23
    # Try to build a graph
    # Start with a random 3-regular-like graph and adjust
    # Actually, let's just try adding edges randomly and checking constraints

    for _ in range(1000):
        adj = [set() for _ in range(n)]
        edges = []

        # Try to add edges
        possible_edges = [(u, v) for u in range(n) for v in range(u + 1, n)]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if len(adj[u]) < 6 and len(adj[v]) < 6:
                # Check if adding (u, v) creates a cycle of length 3, 4, 5
                # A cycle of length 3 is created if u and v share a neighbor
                if adj[u].intersection(adj[v]):
                    continue

                # A cycle of length 4 is created if there is a path of length 3 between u and v
                # A cycle of length 5 is created if there is a path of length 4 between u and v

                # Temporarily add edge
                adj[u].add(v)
                adj[v].add(u)

                if not is_girth_at_least_6(adj, n):
                    adj[u].remove(v)
                    adj[v].remove(u)
                else:
                    edges.append((u, v))

        # Check if all degrees are between 3 and 6
        if all(3 <= len(adj[i]) <= 6 for i in range(n)):
            return edges
    return None

result = solve()
