def check_graph(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check degrees
    for i in range(n):
        if not (3 <= len(adj[i]) <= 6):
            return False, f"Vertex {i} has degree {len(adj[i])}"

    # Check girth
    def get_shortest_cycle(adj, n):
        for i in range(n):
            # BFS to find shortest cycle
            dist = {i: 0}
            parent = {i: None}
            queue = [i]
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif v != parent[u]:
                        # Cycle found
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < 6:
                            return cycle_len
        return float('inf')

    girth = get_shortest_cycle(adj, n)
    if girth < 6:
        return False, f"Girth is {girth}"

    return True, "OK"

